from PIL import Image
import numpy as np,sys
sys.path.insert(0,'/opt/tools');from rcb_client import Robot
r=Robot();spec=r.spec()
for cam in ['egocentric_mirrored_camera','over_shoulder_left_camera']:
 im=np.array(Image.open('/app/output/initial/'+cam+'.png')); d=np.load('/app/output/initial/'+cam+'_depth.npy')
 E=np.array(spec['cameras'][cam]['mount']['extrinsic_cv']); f=spec['cameras'][cam]['intrinsic_cv'][0][0];cx=spec['cameras'][cam]['intrinsic_cv'][0][2];cy=spec['cameras'][cam]['intrinsic_cv'][1][2]
 R,G,B=im[:,:,0].astype(float),im[:,:,1].astype(float),im[:,:,2].astype(float)
 masks={'red':(R>70)&(R>G*2)&(R>B*2)&(G<80)&(B<80),'blue':(B>50)&(B>R*2)&(B>G*1.4)&(R<60),'green':(G>20)&(G>R*1.5)&(G>B*1.5)&(B<50),'yellow':(R>100)&(G>100)&(B<60)&(G>R*.68)&(R>G*.83)}
 print('\n',cam)
 for name,m in masks.items():
  yy,xx=np.where(m&(d>0));dep=d[yy,xx]; xc=(xx-cx)/f*dep; yc=(yy-cy)/f*dep; C=np.stack([xc,yc,dep,np.ones(len(dep))],1);X=(C@np.linalg.inv(np.vstack([E,[0,0,0,1]])).T)[:,:3]
  # only block-sized component/window and upper surface pixels
  if name=='red': region=(xx<400)&(yy<230)
  elif name=='blue':region=(xx>390)&(xx<470)&(yy<250)
  elif name=='green':region=(xx>520)&(xx<600)&(yy<220)
  else:region=(xx>485)&(xx<545)&(yy<250)
  for desc,sel in [('all',region),('top',region&(X[:,2]>.045)),('top2',region&(X[:,2]>.049))]:
   if np.sum(sel): print(name,desc,'n',np.sum(sel),'xyz median',np.round(np.median(X[sel],0),4),'xy range',np.round(np.percentile(X[sel,:2],[10,90],axis=0),4).tolist())
PY

